return $input.all().map(item => {
  // Extract form fields (adjust field names if your form labels differ)
  const email = (item.json['Email'] || item.json.body?.['Email'] || '').toString().trim();
  const phone = (item.json['WhatsApp Number'] || item.json.body?.['WhatsApp Number'] || '').toString().trim();

  // Regular expressions for validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  // Accepts international format starting with + (e.g., +234...) or local numbers (e.g., 080...)
  const phoneRegex = /^(\+\d{1,3}|0)\d{9,13}$/;

  const isEmailValid = emailRegex.test(email);
  const isPhoneValid = phoneRegex.test(phone.replace(/[\s-]/g, ''));

  const errors = [];
  if (!isEmailValid) errors.push('Invalid email address format.');
  if (!isPhoneValid) errors.push('Invalid phone number format.');

  return {
    json: {
      ...item.json,
      isValid: errors.length === 0,
      validationErrors: errors
    }
  };
});
